import csv
from collections import defaultdict
from datetime import datetime

carrier_data = {}

with open('bookstore_orders.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'] != 'Delivered':
            continue

        carrier = row['carrier_name']
        if not carrier:
            carrier = "Unknown"

        estimated_str = row['estimated_delivery_date']
        actual_str = row['actual_delivery_date']

        if not estimated_str or not actual_str:
            continue

        if carrier not in carrier_data:
            carrier_data[carrier] = {'TotalDelivered': 0, 'OnTimeDelivered': 0}

        carrier_data[carrier]['TotalDelivered'] += 1

        try:
            estimated = datetime.strptime(estimated_str, '%Y-%m-%d')
            actual = datetime.strptime(actual_str, '%Y-%m-%d')
            if actual <= estimated:
                carrier_data[carrier]['OnTimeDelivered'] += 1
        except ValueError:
            continue

final_list = []
for carrier, data in carrier_data.items():
    total = data['TotalDelivered']
    on_time = data['OnTimeDelivered']
    ot_pct = (on_time / total) * 100 if total > 0 else 0.0

    final_list.append({
        'CarrierName': carrier,
        'TotalDelivered': total,
        'OnTimeDelivered': on_time,
        'OnTimePct': round(ot_pct, 2)
    })

# Sort by OnTimePct descending
final_list.sort(key=lambda x: x['OnTimePct'], reverse=True)

with open('carrier-otd.csv', mode='w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct'])
    writer.writeheader()
    writer.writerows(final_list)

